-- Schema of a VooSquare database made by the release before versioned migrations (src/migrate.js).
-- Generated by booting that release on an empty database. Used by test/safety.js to prove old databases upgrade cleanly.
-- Never edit: it is a picture of the past.
CREATE TABLE aff_affiliates(
  id INTEGER PRIMARY KEY, user_id INTEGER UNIQUE NOT NULL, code TEXT UNIQUE NOT NULL, status TEXT DEFAULT 'pending',
  display_name TEXT DEFAULT '', hide_name INTEGER DEFAULT 0, kind TEXT DEFAULT 'individual', company TEXT DEFAULT '', country TEXT DEFAULT '',
  telegram TEXT DEFAULT '', whatsapp TEXT DEFAULT '', languages TEXT DEFAULT '[]', application TEXT DEFAULT '{}', traffic TEXT DEFAULT '{}',
  app_step INTEGER DEFAULT 0, applied_at INTEGER, approved_at INTEGER, decided_by INTEGER, decided_at INTEGER, decline_reasons TEXT DEFAULT '[]',
  reapply_after INTEGER DEFAULT 0, info_request TEXT DEFAULT '', info_requested_by INTEGER, escalated INTEGER DEFAULT 0,
  tier INTEGER DEFAULT 0, tier_override INTEGER, tier_floor INTEGER, tier_floor_until INTEGER DEFAULT 0, tier_grace_month TEXT DEFAULT '',
  tier_set_at INTEGER, legend_pending INTEGER DEFAULT 0, legend_approved INTEGER DEFAULT 0,
  activated_at INTEGER, health_state TEXT DEFAULT 'inactive', health_since INTEGER, grace_until INTEGER DEFAULT 0, health_exempt INTEGER DEFAULT 0,
  kyc_status TEXT DEFAULT 'none', kyc_provider_ref TEXT DEFAULT '', kyc_reason TEXT DEFAULT '', kyc_updated_at INTEGER,
  fraud_score INTEGER DEFAULT 0, cpa_paused INTEGER DEFAULT 0, cpa_paused_reason TEXT DEFAULT '', cpa_started_at INTEGER,
  general_manager_id INTEGER, private_manager_id INTEGER, parent_affiliate_id INTEGER, sub_code TEXT UNIQUE,
  wallet_usdt TEXT DEFAULT '', wallet_btc TEXT DEFAULT '', payout_method TEXT DEFAULT 'usdt_trc20',
  tax_country TEXT DEFAULT '', tax_id TEXT DEFAULT '', terms_version TEXT DEFAULT '', terms_accepted_at INTEGER,
  marketing INTEGER DEFAULT 0, notif_prefs TEXT DEFAULT '{}', api_key_hash TEXT UNIQUE, api_key_prefix TEXT DEFAULT '', api_ips TEXT DEFAULT '[]',
  welcome_seen INTEGER DEFAULT 0, pause_reason TEXT DEFAULT '', created_at INTEGER, updated_at INTEGER, closed_at INTEGER
, tier_month TEXT DEFAULT '', health_count INTEGER DEFAULT 0);
CREATE TABLE aff_announcements(
  id INTEGER PRIMARY KEY, kind TEXT DEFAULT 'news', title TEXT NOT NULL, body TEXT DEFAULT '', link TEXT DEFAULT '', audience TEXT DEFAULT '{"kind":"all"}',
  channels TEXT DEFAULT '{"dashboard":true}', pinned INTEGER DEFAULT 0, effective_at INTEGER, send_at INTEGER, expires_at INTEGER DEFAULT 0,
  sent_at INTEGER, recipients INTEGER DEFAULT 0, created_by INTEGER, created_at INTEGER
);
CREATE TABLE aff_attributions(
  customer_user_id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, click_id INTEGER, method TEXT DEFAULT 'link', coupon_code TEXT DEFAULT '',
  pre_existing INTEGER DEFAULT 0, blocked TEXT DEFAULT '', click_at INTEGER, locked_at INTEGER, cust_ref TEXT DEFAULT '', country TEXT DEFAULT '',
  device TEXT DEFAULT '', sub1 TEXT DEFAULT '', sub2 TEXT DEFAULT '', sub3 TEXT DEFAULT '', sub4 TEXT DEFAULT '', sub5 TEXT DEFAULT '', ext_click_id TEXT DEFAULT ''
);
CREATE TABLE aff_audit(
  id INTEGER PRIMARY KEY, actor_id INTEGER, action TEXT NOT NULL, affiliate_id INTEGER, target TEXT DEFAULT '', before TEXT DEFAULT '', after TEXT DEFAULT '', created_at INTEGER
);
CREATE TABLE aff_clawbacks(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, commission_ids TEXT DEFAULT '[]', amount_cents INTEGER DEFAULT 0, reason TEXT DEFAULT '',
  status TEXT DEFAULT 'pending', proposed_by INTEGER, decided_by INTEGER, decided_at INTEGER, created_at INTEGER
);
CREATE TABLE aff_clicks(
  id INTEGER PRIMARY KEY, uid TEXT UNIQUE NOT NULL, affiliate_id INTEGER NOT NULL, link_id INTEGER, product_key TEXT DEFAULT '',
  sub1 TEXT DEFAULT '', sub2 TEXT DEFAULT '', sub3 TEXT DEFAULT '', sub4 TEXT DEFAULT '', sub5 TEXT DEFAULT '', ext_click_id TEXT DEFAULT '',
  ip_hash TEXT DEFAULT '', net_hash TEXT DEFAULT '', ua_hash TEXT DEFAULT '', fp_hash TEXT DEFAULT '', country TEXT DEFAULT '', device TEXT DEFAULT '',
  referrer TEXT DEFAULT '', landing TEXT DEFAULT '', kind TEXT DEFAULT 'link', proxy INTEGER DEFAULT 0, existing_user INTEGER, created_at INTEGER
);
CREATE TABLE aff_commissions(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, type TEXT NOT NULL, amount_cents INTEGER NOT NULL, base_cents INTEGER DEFAULT 0,
  rate_bp INTEGER DEFAULT 0, product_key TEXT DEFAULT '', customer_user_id INTEGER, conversion_id INTEGER, source_commission_id INTEGER,
  hold_until INTEGER DEFAULT 0, status TEXT NOT NULL, reason TEXT DEFAULT '', note TEXT DEFAULT '', payout_id INTEGER, provisional INTEGER DEFAULT 0,
  approved_by INTEGER, uniq_key TEXT UNIQUE, created_at INTEGER, released_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_contest_scores(
  contest_id INTEGER NOT NULL, affiliate_id INTEGER NOT NULL, points INTEGER DEFAULT 0, multiplier_bp INTEGER DEFAULT 10000, score INTEGER DEFAULT 0,
  customers INTEGER DEFAULT 0, revenue_cents INTEGER DEFAULT 0, reached_at INTEGER, removed INTEGER DEFAULT 0, disqualified INTEGER DEFAULT 0,
  dq_reason TEXT DEFAULT '', rank INTEGER, prev_rank INTEGER, updated_at INTEGER, PRIMARY KEY(contest_id, affiliate_id)
);
CREATE TABLE aff_contests(
  id INTEGER PRIMARY KEY, title TEXT NOT NULL, kind TEXT DEFAULT 'monthly', description TEXT DEFAULT '', rules TEXT DEFAULT '',
  banner_upload TEXT DEFAULT '', images TEXT DEFAULT '[]', theme TEXT DEFAULT '{}', starts_at INTEGER, ends_at INTEGER, qual_days INTEGER DEFAULT 0,
  products TEXT DEFAULT '[]', geos TEXT DEFAULT '[]', scoring TEXT DEFAULT '{}', min_points INTEGER DEFAULT 0, multipliers INTEGER DEFAULT 1,
  prizes TEXT DEFAULT '[]', rising TEXT DEFAULT '{}', milestone TEXT DEFAULT '{}', eligibility TEXT DEFAULT '{}', pool_cents INTEGER DEFAULT 0,
  announce INTEGER DEFAULT 1, published INTEGER DEFAULT 1, cancelled INTEGER DEFAULT 0, cancel_note TEXT DEFAULT '',
  final_by INTEGER, final_at INTEGER, signoff_by INTEGER, signoff_at INTEGER, winners TEXT DEFAULT '[]', announced_at INTEGER,
  created_by INTEGER, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_conversions(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, customer_user_id INTEGER, product_key TEXT DEFAULT '', plan TEXT DEFAULT '',
  event_type TEXT NOT NULL, amount_cents INTEGER DEFAULT 0, source TEXT DEFAULT '', source_id INTEGER, source_key TEXT UNIQUE NOT NULL,
  status TEXT DEFAULT 'tracked', payment_no INTEGER DEFAULT 0, related_id INTEGER, country TEXT DEFAULT '', note TEXT DEFAULT '',
  occurred_at INTEGER, received_at INTEGER
, reversed_cents INTEGER DEFAULT 0);
CREATE TABLE aff_coupons(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, code TEXT UNIQUE NOT NULL, product_key TEXT DEFAULT '', discount_pct INTEGER DEFAULT 0,
  max_uses INTEGER DEFAULT 0, uses INTEGER DEFAULT 0, geos TEXT DEFAULT '[]', active INTEGER DEFAULT 1, created_by INTEGER, created_at INTEGER
);
CREATE TABLE aff_cpa_reviews(
  id INTEGER PRIMARY KEY, conversion_id INTEGER UNIQUE, commission_id INTEGER, affiliate_id INTEGER NOT NULL, customer_user_id INTEGER,
  product_key TEXT DEFAULT '', plan TEXT DEFAULT '', amount_cents INTEGER DEFAULT 0, model TEXT DEFAULT 'cpa', risk INTEGER DEFAULT 0,
  verdict TEXT DEFAULT 'unique', signals TEXT DEFAULT '[]', status TEXT DEFAULT 'pending', reviewer_id INTEGER, decided_at INTEGER,
  decline_reason TEXT DEFAULT '', note TEXT DEFAULT '', extended_days INTEGER DEFAULT 0, created_at INTEGER
);
CREATE TABLE aff_creatives(
  id INTEGER PRIMARY KEY, title TEXT DEFAULT '', product_key TEXT DEFAULT '', format TEXT DEFAULT '', size TEXT DEFAULT '', language TEXT DEFAULT 'English',
  platform TEXT DEFAULT '', geo TEXT DEFAULT '', copy_text TEXT DEFAULT '', landing_url TEXT DEFAULT '', upload_id TEXT DEFAULT '', file_url TEXT DEFAULT '',
  min_tier INTEGER DEFAULT 0, public_from INTEGER DEFAULT 0, early_access INTEGER DEFAULT 1, active INTEGER DEFAULT 1, downloads INTEGER DEFAULT 0,
  copies INTEGER DEFAULT 0, created_by INTEGER, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_customers(
  user_id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, first_payment_at INTEGER, first_product TEXT DEFAULT '', first_plan TEXT DEFAULT '',
  first_amount_cents INTEGER DEFAULT 0, payments INTEGER DEFAULT 0, total_cents INTEGER DEFAULT 0, refunded_cents INTEGER DEFAULT 0,
  refunds INTEGER DEFAULT 0, chargebacks INTEGER DEFAULT 0, first_refund_at INTEGER, last_payment_at INTEGER,
  qualified_at INTEGER, qualify_rule TEXT DEFAULT '', model TEXT DEFAULT '', model_at INTEGER, cpa_conversion_id INTEGER, paid_before INTEGER DEFAULT 0
);
CREATE TABLE aff_deal_requests(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, requested_by INTEGER, source TEXT DEFAULT 'manager', product_key TEXT DEFAULT '', plan TEXT DEFAULT '',
  model TEXT DEFAULT 'cpa', cpa_cents INTEGER DEFAULT 0, rate_bp INTEGER DEFAULT 0, monthly_cap INTEGER DEFAULT 0, tier_floor INTEGER, floor_until INTEGER DEFAULT 0,
  traffic TEXT DEFAULT '[]', geos TEXT DEFAULT '[]', expected INTEGER DEFAULT 0, sample_url TEXT DEFAULT '', reason TEXT DEFAULT '',
  needs_owner INTEGER DEFAULT 0, status TEXT DEFAULT 'pending', decided_by INTEGER, decided_at INTEGER, decision_note TEXT DEFAULT '', deal_id INTEGER, created_at INTEGER
);
CREATE TABLE aff_deals(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, product_key TEXT NOT NULL, plan TEXT DEFAULT '', model TEXT DEFAULT 'cpa',
  cpa_cents INTEGER DEFAULT 0, rate_bp INTEGER DEFAULT 0, monthly_cap INTEGER DEFAULT 50, traffic TEXT DEFAULT '[]', geos TEXT DEFAULT '[]',
  starts_at INTEGER, ends_at INTEGER DEFAULT 0, status TEXT DEFAULT 'active', pause_reason TEXT DEFAULT '',
  created_by INTEGER, approved_by INTEGER, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_identities(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, kind TEXT NOT NULL, value TEXT NOT NULL, at INTEGER, UNIQUE(user_id, kind, value)
);
CREATE TABLE aff_kyc_docs(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, upload_id TEXT NOT NULL, doc_type TEXT DEFAULT 'id', created_at INTEGER
);
CREATE TABLE aff_links(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, code TEXT UNIQUE NOT NULL, name TEXT DEFAULT '', product_key TEXT DEFAULT '',
  dest_url TEXT DEFAULT '', sub1 TEXT DEFAULT '', sub2 TEXT DEFAULT '', sub3 TEXT DEFAULT '', sub4 TEXT DEFAULT '', sub5 TEXT DEFAULT '',
  click_macro TEXT DEFAULT '', archived INTEGER DEFAULT 0, created_at INTEGER
);
CREATE TABLE aff_managers(
  user_id INTEGER PRIMARY KEY, kinds TEXT DEFAULT '["general"]', languages TEXT DEFAULT '[]', countries TEXT DEFAULT '[]',
  capacity INTEGER DEFAULT 0, hours TEXT DEFAULT '', telegram TEXT DEFAULT '', active INTEGER DEFAULT 1, rr_at INTEGER DEFAULT 0, created_at INTEGER
);
CREATE TABLE aff_notes(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, author_id INTEGER, body TEXT NOT NULL, shared INTEGER DEFAULT 0, created_at INTEGER
);
CREATE TABLE aff_notifications(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, category TEXT DEFAULT 'Money', kind TEXT DEFAULT '', text TEXT NOT NULL,
  product_key TEXT DEFAULT '', link TEXT DEFAULT '', read_at INTEGER, created_at INTEGER
);
CREATE TABLE aff_offer_changes(
  id INTEGER PRIMARY KEY, scope TEXT DEFAULT 'program', affiliate_id INTEGER, deal_id INTEGER, product_key TEXT DEFAULT '', field TEXT NOT NULL,
  old_value TEXT DEFAULT '', new_value TEXT DEFAULT '', direction TEXT DEFAULT 'increase', announced_at INTEGER, effective_at INTEGER,
  applied_at INTEGER, reminded_at INTEGER, created_by INTEGER, note TEXT DEFAULT ''
);
CREATE TABLE aff_payouts(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, amount_cents INTEGER NOT NULL, fee_cents INTEGER DEFAULT 0, method TEXT NOT NULL,
  wallet TEXT NOT NULL, status TEXT DEFAULT 'requested', requested_at INTEGER, sla_due_at INTEGER, approved_by INTEGER, approved_at INTEGER,
  processing_by INTEGER, processing_at INTEGER, paid_by INTEGER, paid_at INTEGER, tx_hash TEXT DEFAULT '', provider TEXT DEFAULT 'manual',
  provider_ref TEXT DEFAULT '', provider_status TEXT DEFAULT '', reason TEXT DEFAULT '', hold_reason TEXT DEFAULT '', note TEXT DEFAULT '',
  receipt_no TEXT UNIQUE, period_from INTEGER, period_to INTEGER, tier INTEGER DEFAULT 0
);
CREATE TABLE aff_plans(
  product_key TEXT NOT NULL, plan TEXT NOT NULL, price_cents INTEGER DEFAULT 0, synced_at INTEGER, PRIMARY KEY(product_key, plan)
);
CREATE TABLE aff_postback_deliveries(
  id INTEGER PRIMARY KEY, postback_id INTEGER NOT NULL, affiliate_id INTEGER NOT NULL, event TEXT, event_key TEXT, conversion_id INTEGER,
  url TEXT DEFAULT '', method TEXT DEFAULT 'GET', body TEXT DEFAULT '', status TEXT DEFAULT 'pending', response_code INTEGER, response_ms INTEGER,
  attempts INTEGER DEFAULT 0, next_at INTEGER, last_error TEXT DEFAULT '', test INTEGER DEFAULT 0, created_at INTEGER, updated_at INTEGER,
  UNIQUE(postback_id, event_key)
);
CREATE TABLE aff_postbacks(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, name TEXT DEFAULT '', url TEXT NOT NULL, method TEXT DEFAULT 'GET',
  events TEXT DEFAULT '[]', products TEXT DEFAULT '[]', active INTEGER DEFAULT 1, secret TEXT DEFAULT '', created_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_receipts(
  id INTEGER PRIMARY KEY, payout_id INTEGER UNIQUE NOT NULL, receipt_no TEXT UNIQUE NOT NULL, affiliate_id INTEGER NOT NULL, issued_at INTEGER, data TEXT DEFAULT '{}'
);
CREATE TABLE aff_telegram(
  affiliate_id INTEGER PRIMARY KEY, chat_id TEXT DEFAULT '', username TEXT DEFAULT '', verified INTEGER DEFAULT 0, code_hash TEXT DEFAULT '',
  code_expires INTEGER DEFAULT 0, prefs TEXT DEFAULT '{}', quiet_from TEXT DEFAULT '', quiet_to TEXT DEFAULT '', tz TEXT DEFAULT 'Africa/Lagos',
  linked_at INTEGER, updated_at INTEGER
);
CREATE TABLE aff_tg_outbox(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER, chat_id TEXT NOT NULL, kind TEXT DEFAULT '', text TEXT NOT NULL, status TEXT DEFAULT 'queued',
  attempts INTEGER DEFAULT 0, next_at INTEGER, error TEXT DEFAULT '', created_at INTEGER, sent_at INTEGER
);
CREATE TABLE aff_tier_history(
  id INTEGER PRIMARY KEY, affiliate_id INTEGER NOT NULL, from_tier INTEGER, to_tier INTEGER, reason TEXT DEFAULT '', score_x100 INTEGER DEFAULT 0, at INTEGER
);
CREATE TABLE audit(id INTEGER PRIMARY KEY, user_id INTEGER, action TEXT, detail TEXT DEFAULT '', created_at INTEGER);
CREATE TABLE canned(id INTEGER PRIMARY KEY, title TEXT, body TEXT, product_id INTEGER);
CREATE TABLE courses(
  id INTEGER PRIMARY KEY, slug TEXT UNIQUE, title TEXT, track TEXT DEFAULT 'Foundations', level TEXT DEFAULT 'Beginner',
  author_key TEXT DEFAULT 'team', author_name TEXT DEFAULT 'Zedapex team', author_role TEXT DEFAULT 'Media buyers',
  description TEXT DEFAULT '', grad TEXT DEFAULT '', mark TEXT DEFAULT '', premium INTEGER DEFAULT 0,
  sort INTEGER DEFAULT 0, published INTEGER DEFAULT 1, created_at INTEGER
);
CREATE TABLE email_queue(
  id INTEGER PRIMARY KEY, user_id INTEGER, to_email TEXT, template TEXT, vars TEXT DEFAULT '{}',
  send_at INTEGER, sent_at INTEGER, status TEXT DEFAULT 'queued', attempts INTEGER DEFAULT 0, error TEXT DEFAULT ''
);
CREATE TABLE email_sequence(key TEXT PRIMARY KEY, delay_hours REAL, enabled INTEGER DEFAULT 1, sort INTEGER DEFAULT 0);
CREATE TABLE email_templates(
  key TEXT PRIMARY KEY, name TEXT, subject TEXT, preheader TEXT DEFAULT '', html TEXT, text TEXT DEFAULT '',
  marketing INTEGER DEFAULT 0, updated_at INTEGER
);
CREATE TABLE events(
  id INTEGER PRIMARY KEY, product_id INTEGER, user_id INTEGER, ext_id TEXT, type TEXT, label TEXT DEFAULT '',
  value_usd REAL DEFAULT 0, created_at INTEGER, received_at INTEGER, plan TEXT DEFAULT '', ref_event TEXT DEFAULT '', country TEXT DEFAULT '', UNIQUE(product_id, ext_id)
);
CREATE TABLE lessons(
  id INTEGER PRIMARY KEY, course_id INTEGER, idx INTEGER DEFAULT 0, title TEXT, minutes INTEGER DEFAULT 5,
  premium INTEGER DEFAULT 0, steps TEXT DEFAULT '[]', takeaways TEXT DEFAULT '[]', action TEXT DEFAULT '',
  quiz TEXT DEFAULT 'null', published INTEGER DEFAULT 1
);
CREATE TABLE login_codes(
  email TEXT PRIMARY KEY, code_hash TEXT, expires INTEGER, attempts INTEGER DEFAULT 0,
  name TEXT, ref TEXT, product_id INTEGER, created_at INTEGER
, aff_coupon TEXT DEFAULT '');
CREATE TABLE messages(
  id INTEGER PRIMARY KEY, room_id INTEGER, user_id INTEGER, body TEXT, reply_to INTEGER,
  pinned INTEGER DEFAULT 0, deleted INTEGER DEFAULT 0, created_at INTEGER
, upload_id TEXT);
CREATE TABLE orders(
  id INTEGER PRIMARY KEY, ref TEXT UNIQUE, user_id INTEGER, item_type TEXT, item_id INTEGER, item_name TEXT,
  amount_usd REAL, currency TEXT, amount REAL, method_id INTEGER, status TEXT DEFAULT 'pending',
  provider_ref TEXT DEFAULT '', proof TEXT DEFAULT '', note TEXT DEFAULT '', created_at INTEGER, paid_at INTEGER
, proof_upload TEXT DEFAULT '', aff_coupon TEXT DEFAULT '');
CREATE TABLE payment_methods(
  id INTEGER PRIMARY KEY, type TEXT, name TEXT, currency TEXT DEFAULT 'USD', rate REAL DEFAULT 1,
  config TEXT DEFAULT '{}', enabled INTEGER DEFAULT 0, sort INTEGER DEFAULT 0, note TEXT DEFAULT '', countries TEXT DEFAULT '[]'
);
CREATE TABLE payout_methods(
  user_id INTEGER PRIMARY KEY, type TEXT NOT NULL, details TEXT DEFAULT '{}', updated_at INTEGER
);
CREATE TABLE payouts(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, amount_usd REAL NOT NULL, method TEXT DEFAULT '{}',
  status TEXT DEFAULT 'requested', reference TEXT DEFAULT '', note TEXT DEFAULT '', rate REAL DEFAULT 0,
  requested_at INTEGER, decided_by INTEGER, decided_at INTEGER, paid_at INTEGER
);
CREATE TABLE posts(
  id INTEGER PRIMARY KEY, slug TEXT UNIQUE, title TEXT, category TEXT DEFAULT 'Playbook',
  author_key TEXT DEFAULT 'team', author_name TEXT DEFAULT 'Zedapex team', author_role TEXT DEFAULT '',
  excerpt TEXT DEFAULT '', minutes INTEGER DEFAULT 4, grad TEXT DEFAULT '', mark TEXT DEFAULT '', body TEXT DEFAULT '[]',
  premium INTEGER DEFAULT 0, published INTEGER DEFAULT 1, featured INTEGER DEFAULT 0, created_at INTEGER
);
CREATE TABLE products(
  id INTEGER PRIMARY KEY, slug TEXT UNIQUE, name TEXT, stage TEXT DEFAULT '', status TEXT DEFAULT 'live',
  tagline TEXT DEFAULT '', description TEXT DEFAULT '', url TEXT DEFAULT '', icon TEXT DEFAULT '', color TEXT DEFAULT '#00A86B',
  tint TEXT DEFAULT '#E7F8F0', offer TEXT DEFAULT '', sort INTEGER DEFAULT 0, visible INTEGER DEFAULT 1, hub INTEGER DEFAULT 0,
  external INTEGER DEFAULT 0, sso INTEGER DEFAULT 0, client_id TEXT UNIQUE, client_secret TEXT, api_key TEXT UNIQUE,
  redirect_uris TEXT DEFAULT '[]', summary_url TEXT DEFAULT '', support_webhook TEXT DEFAULT '', support_greeting TEXT DEFAULT '',
  created_at INTEGER
);
CREATE TABLE progress(user_id INTEGER, lesson_id INTEGER, done_at INTEGER, PRIMARY KEY(user_id, lesson_id));
CREATE TABLE reactions(message_id INTEGER, user_id INTEGER, emoji TEXT, PRIMARY KEY(message_id, user_id, emoji));
CREATE TABLE release_notes(
  id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT DEFAULT '', link_url TEXT DEFAULT '', link_text TEXT DEFAULT '',
  published INTEGER DEFAULT 1, created_by INTEGER, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE release_seen(user_id INTEGER NOT NULL, note_id INTEGER NOT NULL, seen_at INTEGER, PRIMARY KEY(user_id, note_id));
CREATE TABLE room_access(user_id INTEGER, room_id INTEGER, until INTEGER, PRIMARY KEY(user_id, room_id));
CREATE TABLE room_applications(
  id INTEGER PRIMARY KEY, room_id INTEGER NOT NULL, user_id INTEGER NOT NULL, answers TEXT DEFAULT '[]',
  status TEXT DEFAULT 'pending', note_to_member TEXT DEFAULT '', decided_by INTEGER, decided_at INTEGER,
  created_at INTEGER, approved_until INTEGER DEFAULT 0, seat_override INTEGER DEFAULT 0, paid_at INTEGER
);
CREATE TABLE room_reads(user_id INTEGER, room_id INTEGER, last_id INTEGER, PRIMARY KEY(user_id, room_id));
CREATE TABLE rooms(
  id INTEGER PRIMARY KEY, slug TEXT UNIQUE, name TEXT, topic TEXT DEFAULT 'General', description TEXT DEFAULT '',
  icon TEXT DEFAULT 'chat', color TEXT DEFAULT '#00A86B', access TEXT DEFAULT 'free', price_usd REAL DEFAULT 0,
  period_days INTEGER DEFAULT 30, read_only INTEGER DEFAULT 0, slow_secs INTEGER DEFAULT 0, sort INTEGER DEFAULT 0,
  archived INTEGER DEFAULT 0, created_at INTEGER
, images INTEGER DEFAULT 1, approval_required INTEGER DEFAULT 0, seats INTEGER DEFAULT 0, apply_questions TEXT DEFAULT '[]', image_upload TEXT DEFAULT '', cover_upload TEXT DEFAULT '');
CREATE TABLE school_attempts(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, kind TEXT NOT NULL, ref_id INTEGER NOT NULL, score INTEGER, total INTEGER,
  passed INTEGER DEFAULT 0, xp INTEGER DEFAULT 0, at INTEGER
);
CREATE TABLE school_certificates(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, school_id INTEGER NOT NULL, code TEXT UNIQUE NOT NULL, name TEXT DEFAULT '',
  title TEXT DEFAULT '', name_changes INTEGER DEFAULT 0, issued_at INTEGER, revoked_at INTEGER DEFAULT 0, revoked_reason TEXT DEFAULT ''
);
CREATE TABLE school_enrollments(user_id INTEGER NOT NULL, school_id INTEGER NOT NULL, started_at INTEGER, PRIMARY KEY(user_id, school_id));
CREATE TABLE school_grants(user_id INTEGER NOT NULL, kind TEXT NOT NULL, ref_id INTEGER NOT NULL, by_id INTEGER, at INTEGER, PRIMARY KEY(user_id, kind, ref_id));
CREATE TABLE school_lessons(
  id INTEGER PRIMARY KEY, module_id INTEGER NOT NULL, slug TEXT NOT NULL, idx INTEGER DEFAULT 0, title TEXT, minutes INTEGER DEFAULT 10,
  objectives TEXT DEFAULT '[]', steps TEXT DEFAULT '[]', takeaways TEXT DEFAULT '[]', action TEXT DEFAULT '', glossary TEXT DEFAULT '[]',
  quiz TEXT DEFAULT '[]', published INTEGER DEFAULT 1, edited INTEGER DEFAULT 0, src_hash TEXT DEFAULT '', updated_at INTEGER, steps_n INTEGER DEFAULT 0, say_intro TEXT DEFAULT '', say_outro TEXT DEFAULT '', say_src TEXT DEFAULT '[]',
  UNIQUE(module_id, slug)
);
CREATE TABLE school_module_state(
  user_id INTEGER NOT NULL, module_id INTEGER NOT NULL, started_at INTEGER, passed_at INTEGER, skip_wait_at INTEGER, granted INTEGER DEFAULT 0,
  PRIMARY KEY(user_id, module_id)
);
CREATE TABLE school_modules(
  id INTEGER PRIMARY KEY, school_id INTEGER NOT NULL, slug TEXT NOT NULL, title TEXT, summary TEXT DEFAULT '', sort INTEGER DEFAULT 0,
  exam TEXT DEFAULT '[]', published INTEGER DEFAULT 1, file TEXT DEFAULT '', updated_at INTEGER, exam_n INTEGER DEFAULT 0, UNIQUE(school_id, slug)
);
CREATE TABLE school_papers(
  id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, kind TEXT NOT NULL, ref_id INTEGER NOT NULL, qkeys TEXT DEFAULT '[]',
  created_at INTEGER, submitted_at INTEGER
);
CREATE TABLE school_partners(
  id INTEGER PRIMARY KEY, vertical TEXT NOT NULL, name TEXT NOT NULL, logo_upload TEXT DEFAULT '', description TEXT DEFAULT '',
  highlights TEXT DEFAULT '[]', url TEXT DEFAULT '', cta TEXT DEFAULT '', badge TEXT DEFAULT '', sort INTEGER DEFAULT 0, enabled INTEGER DEFAULT 1,
  clicks INTEGER DEFAULT 0, last_click_at INTEGER, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE school_prefs(user_id INTEGER PRIMARY KEY, vertical TEXT DEFAULT '', chosen_at INTEGER);
CREATE TABLE school_progress(
  user_id INTEGER NOT NULL, lesson_id INTEGER NOT NULL, best_score INTEGER DEFAULT 0, total INTEGER DEFAULT 0, attempts INTEGER DEFAULT 0,
  passed_at INTEGER, last_at INTEGER, granted INTEGER DEFAULT 0, PRIMARY KEY(user_id, lesson_id)
);
CREATE TABLE school_schools(
  id INTEGER PRIMARY KEY, slug TEXT UNIQUE NOT NULL, title TEXT, subtitle TEXT DEFAULT '', level TEXT DEFAULT '',
  sort INTEGER DEFAULT 0, premium INTEGER DEFAULT 0, cert_title TEXT DEFAULT '', published INTEGER DEFAULT 1, created_at INTEGER
, track TEXT DEFAULT 'main', vertical TEXT DEFAULT '');
CREATE TABLE school_students(user_id INTEGER PRIMARY KEY, number TEXT UNIQUE, created_at INTEGER);
CREATE TABLE sessions(token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL, created_at INTEGER, expires INTEGER);
CREATE TABLE settings(key TEXT PRIMARY KEY, value TEXT);
CREATE TABLE sso_codes(code_hash TEXT PRIMARY KEY, user_id INTEGER, product_id INTEGER, redirect_uri TEXT, expires INTEGER);
CREATE TABLE ticket_messages(
  id INTEGER PRIMARY KEY, ticket_id INTEGER, author_type TEXT, author_id INTEGER, body TEXT, internal INTEGER DEFAULT 0, created_at INTEGER
, upload_id TEXT);
CREATE TABLE tickets(
  id INTEGER PRIMARY KEY, product_id INTEGER, user_id INTEGER, visitor_token TEXT, email TEXT DEFAULT '', name TEXT DEFAULT '',
  subject TEXT DEFAULT '', status TEXT DEFAULT 'open', priority TEXT DEFAULT 'normal', assignee_id INTEGER,
  channel TEXT DEFAULT 'voosquare', external_ref TEXT DEFAULT '', page_url TEXT DEFAULT '',
  staff_unread INTEGER DEFAULT 1, customer_unread INTEGER DEFAULT 0, created_at INTEGER, updated_at INTEGER
);
CREATE TABLE tool_saves(
  id INTEGER PRIMARY KEY, user_id INTEGER NOT NULL, tool TEXT NOT NULL, name TEXT DEFAULT '', data TEXT DEFAULT '{}', created_at INTEGER
);
CREATE TABLE uploads(
  id TEXT PRIMARY KEY, user_id INTEGER NOT NULL, sha TEXT, mime TEXT, bytes INTEGER, w INTEGER, h INTEGER,
  thumb INTEGER DEFAULT 0, purpose TEXT DEFAULT 'chat', attached_to TEXT DEFAULT '', created_at INTEGER,
  deleted INTEGER DEFAULT 0, purged INTEGER DEFAULT 0
);
CREATE TABLE users(
  id INTEGER PRIMARY KEY, voo_id TEXT UNIQUE NOT NULL, email TEXT UNIQUE NOT NULL,
  name TEXT DEFAULT '', handle TEXT UNIQUE, country TEXT DEFAULT '', avatar TEXT DEFAULT '{}', bio TEXT DEFAULT '',
  role_title TEXT DEFAULT '', perms TEXT DEFAULT '[]', support_scope TEXT DEFAULT '[]',
  premium_until INTEGER DEFAULT 0, premium_notice INTEGER DEFAULT 0,
  banned INTEGER DEFAULT 0, muted_until INTEGER DEFAULT 0,
  ref_code TEXT UNIQUE, referred_by INTEGER, signup_product INTEGER,
  marketing INTEGER DEFAULT 1, onboarded INTEGER DEFAULT 0, xp INTEGER DEFAULT 0,
  created_at INTEGER, last_seen INTEGER
, deactivated INTEGER DEFAULT 0, erased_at INTEGER DEFAULT 0);
CREATE TABLE voice_clips(
  id INTEGER PRIMARY KEY, lesson_id INTEGER NOT NULL, slot TEXT NOT NULL, step_index INTEGER,
  text TEXT DEFAULT '', text_hash TEXT DEFAULT '', file TEXT DEFAULT '', bytes INTEGER DEFAULT 0, duration_ms INTEGER DEFAULT 0,
  chars INTEGER DEFAULT 0, status TEXT DEFAULT 'missing', error TEXT DEFAULT '', err_hash TEXT DEFAULT '', attempts INTEGER DEFAULT 0,
  provider TEXT DEFAULT '', voice TEXT DEFAULT '', generated_at INTEGER, updated_at INTEGER, UNIQUE(lesson_id, slot)
);
CREATE TABLE voice_edits(lesson_id INTEGER NOT NULL, slot TEXT NOT NULL, text TEXT DEFAULT '', by_id INTEGER, at INTEGER, PRIMARY KEY(lesson_id, slot));
CREATE TABLE voice_prefs(user_id INTEGER PRIMARY KEY, enabled INTEGER DEFAULT 1, auto INTEGER DEFAULT 1, captions INTEGER DEFAULT 1, speed REAL DEFAULT 1, updated_at INTEGER);
CREATE INDEX ix_aff_attr_aff ON aff_attributions(affiliate_id, locked_at);
CREATE INDEX ix_aff_audit ON aff_audit(created_at);
CREATE INDEX ix_aff_clicks_aff ON aff_clicks(affiliate_id, created_at);
CREATE INDEX ix_aff_com_aff ON aff_commissions(affiliate_id, status);
CREATE INDEX ix_aff_com_cust ON aff_commissions(customer_user_id, type);
CREATE INDEX ix_aff_com_hold ON aff_commissions(status, hold_until);
CREATE INDEX ix_aff_com_payout ON aff_commissions(payout_id);
CREATE INDEX ix_aff_conv_aff ON aff_conversions(affiliate_id, occurred_at);
CREATE INDEX ix_aff_conv_cust ON aff_conversions(customer_user_id, event_type);
CREATE INDEX ix_aff_cpa_status ON aff_cpa_reviews(status, risk);
CREATE INDEX ix_aff_cust_aff ON aff_customers(affiliate_id, qualified_at);
CREATE INDEX ix_aff_cust_first ON aff_customers(affiliate_id, first_payment_at);
CREATE INDEX ix_aff_deals_aff ON aff_deals(affiliate_id, product_key, status);
CREATE INDEX ix_aff_gm ON aff_affiliates(general_manager_id);
CREATE INDEX ix_aff_ident ON aff_identities(kind, value);
CREATE INDEX ix_aff_links_aff ON aff_links(affiliate_id, archived);
CREATE INDEX ix_aff_notif ON aff_notifications(affiliate_id, id);
CREATE INDEX ix_aff_parent ON aff_affiliates(parent_affiliate_id);
CREATE INDEX ix_aff_payouts_aff ON aff_payouts(affiliate_id, id);
CREATE INDEX ix_aff_payouts_status ON aff_payouts(status, requested_at);
CREATE INDEX ix_aff_pbd_aff ON aff_postback_deliveries(affiliate_id, id);
CREATE INDEX ix_aff_pbd_due ON aff_postback_deliveries(status, next_at);
CREATE INDEX ix_aff_pm ON aff_affiliates(private_manager_id);
CREATE INDEX ix_aff_status ON aff_affiliates(status);
CREATE INDEX ix_aff_tg_due ON aff_tg_outbox(status, next_at);
CREATE INDEX ix_apps_room ON room_applications(room_id, status);
CREATE INDEX ix_apps_user ON room_applications(user_id, room_id);
CREATE INDEX ix_events_type_time ON events(type, created_at);
CREATE INDEX ix_events_user ON events(user_id, id);
CREATE INDEX ix_events_user_type ON events(user_id, type);
CREATE INDEX ix_lessons_course ON lessons(course_id, idx);
CREATE INDEX ix_messages_room ON messages(room_id, id);
CREATE INDEX ix_orders_paid ON orders(status, paid_at);
CREATE INDEX ix_orders_user ON orders(user_id);
CREATE INDEX ix_payouts_status ON payouts(status, requested_at);
CREATE INDEX ix_payouts_user ON payouts(user_id, id);
CREATE INDEX ix_queue_due ON email_queue(status, send_at);
CREATE INDEX ix_school_attempts_user ON school_attempts(user_id, kind, ref_id, at);
CREATE INDEX ix_school_certs_user ON school_certificates(user_id, school_id);
CREATE INDEX ix_school_lessons_mod ON school_lessons(module_id, idx);
CREATE INDEX ix_school_partners_v ON school_partners(vertical, enabled, sort);
CREATE INDEX ix_sessions_user ON sessions(user_id);
CREATE INDEX ix_tickets_status ON tickets(status, updated_at);
